ALTER TABLE "stock_holdings" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "stock_holdings" ADD CONSTRAINT "stock_holdings_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "stock_holdings_user_symbol_unique" ON "stock_holdings" USING btree ("user_id","symbol");--> statement-breakpoint
-- Stock wallets become stock holdings (they only ever held lots: no transactions or transfers).
INSERT INTO "stock_holdings" ("user_id", "symbol", "lots", "sort_order", "created_at")
SELECT "user_id", "stock_symbol", COALESCE("lots", 0), "sort_order", "created_at"
FROM "wallets"
WHERE "type" = 'stock' AND "deleted_at" IS NULL AND "stock_symbol" IS NOT NULL
ON CONFLICT ("user_id", "symbol") DO NOTHING;--> statement-breakpoint
DELETE FROM "email_wallet_links" WHERE "wallet_id" IN (SELECT "id" FROM "wallets" WHERE "type" = 'stock');--> statement-breakpoint
-- If a stock wallet had any transaction or transfer, the foreign keys stop this (nothing is lost).
DELETE FROM "wallets" WHERE "type" = 'stock';
